input.command:
d=$(mktemp -d) && cp "/ux/run/work/invoice.metais" "$d/invoice.js" && cat > "$d/run.js" <<'EOF'
const { renderInvoice } = require('./invoice.js');
const html = renderInvoice({
  number: 'INV-1001', date: '2026-10-23',
  seller: { name: 'Acme <Ltd>', address: '1 Main St' },
  buyer: { name: 'Globex', address: '2 High St' },
  currency: 'USD', taxRate: 0.2,
  lineItems: [
    { description: 'Widget & Co', quantity: 2, unitPrice: 9.5 },
    { description: 'Gadget', quantity: 1, unitPrice: 100 },
  ],
});
console.log(html);
EOF
node "$d/run.js" | grep -E "Widget|Gadget|Subtotal|Tax|Total|Acme" ; rm -rf "$d"

